using Spectre.Console;
using Yubico.YubiKit.Core.Devices;
using Yubico.YubiKit.Ctap2.Examples.FidoTool.Cli.Output;
using Yubico.YubiKit.Ctap2.Examples.FidoTool.Cli.Prompts;
using Yubico.YubiKit.Ctap2.Examples.FidoTool.FidoExamples;

namespace Yubico.YubiKit.Ctap2.Examples.FidoTool.Cli.Menus;

/// <summary>
/// Interactive menu for factory reset of the FIDO application.
/// </summary>
/// <remarks>
/// Human-coordinated only. The post-reinsert selection is not bound to the confirmed physical key and
/// reuses the old transport choice; a different key can be reset. Preflight defaults and current prompt
/// strings are not authoritative transport/timing evidence. ReadLine/confirmation prompts do not honor
/// cancellation while blocked. Follow the sample README's qualified product reset procedure and verify
/// the final physical target; a failed result does not establish unchanged credentials/PIN/settings.
/// </remarks>
public static class ResetMenu
{
    /// <summary>
    /// Runs the factory reset flow with multiple confirmation prompts.
    /// </summary>
    public static async Task RunAsync(CancellationToken cancellationToken)
    {
        OutputHelpers.WriteHeader("Factory Reset");

        var selection = await DeviceSelector.SelectDeviceAsync(cancellationToken);
        if (selection is null)
        {
            return;
        }

        OutputHelpers.WriteActiveDevice(selection.DisplayName);

        var resetTransport = SelectResetTransport(selection.Device.AvailableConnections);

        // Query authenticator for reset-specific capabilities
        var preflight = await ResetAuthenticator.GetPreflightInfoAsync(
            selection.Device, resetTransport, cancellationToken);

        // Check transport restrictions
        if (preflight is { TransportsForReset.Count: > 0 })
        {
            var currentTransport = ToCtapTransport(resetTransport);
            var allowed = preflight.TransportsForReset;
            if (currentTransport is not null && !allowed.Any(t => currentTransport.Equals(t, StringComparison.OrdinalIgnoreCase)))
            {
                OutputHelpers.WriteError(
                    $"Cannot perform FIDO reset over the current transport. " +
                    $"Allowed transports: {string.Join(", ", allowed)}");
                return;
            }
        }

        // Double confirmation
        if (!OutputHelpers.ConfirmDestructive("factory reset the FIDO application"))
        {
            OutputHelpers.WriteInfo("Reset cancelled.");
            return;
        }

        var touchInstruction = preflight?.LongTouchForReset == true
            ? "Press and hold for 10 seconds after re-inserting"
            : "Touch your YubiKey after re-inserting";

        AnsiConsole.WriteLine();
        AnsiConsole.MarkupLine("[yellow]To perform the reset:[/]");
        AnsiConsole.MarkupLine("[yellow]  1. Remove your YubiKey[/]");
        AnsiConsole.MarkupLine("[yellow]  2. Re-insert your YubiKey[/]");
        AnsiConsole.MarkupLine($"[yellow]  3. {touchInstruction}[/]");
        AnsiConsole.WriteLine();

        if (!AnsiConsole.Confirm("Ready to proceed?", defaultValue: false))
        {
            OutputHelpers.WriteInfo("Reset cancelled.");
            return;
        }

        AnsiConsole.MarkupLine("[yellow]Remove your YubiKey now...[/]");
        AnsiConsole.MarkupLine("[grey]Press Enter after re-inserting your YubiKey.[/]");
        Console.ReadLine();

        // Known target-continuity defect: independent selection can return a different physical key.
        var newSelection = await DeviceSelector.SelectDeviceAsync(cancellationToken);
        if (newSelection is null)
        {
            OutputHelpers.WriteError("No YubiKey found after re-insertion.");
            return;
        }

        // Old transport is reused; preflight can fail/default and is not a target/timing guarantee.
        var reinsertedPreflight = await ResetAuthenticator.GetPreflightInfoAsync(
            newSelection.Device, resetTransport, cancellationToken);

        var touchMsg = reinsertedPreflight?.TouchMessage ?? "Touch your YubiKey to confirm.";
        AnsiConsole.MarkupLine($"[yellow]{Markup.Escape(touchMsg)}[/]");

        var result = await AnsiConsole.Status()
            .Spinner(Spinner.Known.Dots)
            .StartAsync("Resetting FIDO application...", async _ =>
                await ResetAuthenticator.ResetAsync(newSelection.Device, resetTransport, cancellationToken));

        if (result.Success)
        {
            AnsiConsole.WriteLine();
            OutputHelpers.WriteSuccess("FIDO application has been factory reset.");
            OutputHelpers.WriteInfo("All credentials, PINs, and settings have been erased.");
        }
        else
        {
            OutputHelpers.WriteError(result.ErrorMessage!);
        }
    }

    internal static ConnectionType SelectResetTransport(ConnectionType availableConnections)
    {
        if ((availableConnections & ConnectionType.HidFido) != 0)
            return ConnectionType.HidFido;
        if ((availableConnections & ConnectionType.SmartCard) != 0)
            return ConnectionType.SmartCard;

        throw new NotSupportedException("FIDO reset requires HID FIDO or SmartCard.");
    }

    internal static string? ToCtapTransport(ConnectionType concreteTransport) => concreteTransport switch
    {
        ConnectionType.HidFido => "usb",
        ConnectionType.SmartCard => null,
        _ => throw new ArgumentException("FIDO reset requires HID FIDO or SmartCard.", nameof(concreteTransport))
    };
}

