/// <summary>
/// Device selector for CTAP2 operations.
/// Supports FIDO HID and SmartCard transports.
/// In non-interactive mode, prefers FIDO HID as the native CTAP2 transport.
/// </summary>
/// <remarks>
/// This is an alternative shared-base selector. Program and menus currently use DeviceSelector instead;
/// do not infer active retry, cancellation or target-binding behavior from this class.
/// </remarks>
public sealed class FidoDeviceSelector : DeviceSelectorBase
{
    /// <summary>
    /// Shared singleton instance.
    /// </summary>
    public static FidoDeviceSelector Instance { get; } = new();

    /// <inheritdoc />
    protected override ConnectionType[] SupportedConnectionTypes { get; } =
    [
        ConnectionType.HidFido,
        ConnectionType.SmartCard
    ];

    /// <inheritdoc />
    protected override string SupportedTransportsDescription => "FIDO HID, SmartCard (USB requires firmware 5.8+)";

    /// <inheritdoc />
    /// <remarks>
    /// Prefers FIDO HID in non-interactive mode as it is the native CTAP2 transport.
    /// Falls back to the first available device if no FIDO HID device is found.
    /// </remarks>
    protected override IYubiKey? AutoSelectDevice(IReadOnlyList<IYubiKey> devices) =>
        devices.FirstOrDefault(d => d.SupportsConnection(ConnectionType.HidFido))
        ?? devices[0];
}

