/// <summary>
/// Credential management operations: enumerate, delete, and update stored credentials.
/// Uses the standard credential-management command (credMgmt), not prototype fallback.
/// </summary>
/// <remarks>
/// Actual support/authorization is separate from firmware metadata. Helpers select protocol 2 without
/// negotiation, borrow PIN input and finally-clear tokens. CredentialManagement borrows the token and
/// does not privately clone it; its Dispose currently does not prevent operations. General catches
/// flatten cancellation/transport/decode provenance and do not establish rollback. Coordinate complete
/// eager enumeration sequences without interleaving other authenticator operations.
/// </remarks>
public static class CredentialManagementExample
{
    /// <summary>
    /// Result of a credential metadata query.
    /// </summary>
    public sealed record MetadataResult
    {
        public bool Success { get; init; }
        public string? ErrorMessage { get; init; }
        public CredentialMetadata? Metadata { get; init; }

        public static MetadataResult Succeeded(CredentialMetadata metadata) =>
            new() { Success = true, Metadata = metadata };

        public static MetadataResult Failed(string error) =>
            new() { Success = false, ErrorMessage = error };
    }

    /// <summary>
    /// Result of enumerating relying parties.
    /// </summary>
    public sealed record EnumerateRpsResult
    {
        public bool Success { get; init; }
        public string? ErrorMessage { get; init; }
        public IReadOnlyList<RelyingPartyInfo> RelyingParties { get; init; } = [];

        public static EnumerateRpsResult Succeeded(IReadOnlyList<RelyingPartyInfo> rps) =>
            new() { Success = true, RelyingParties = rps };

        public static EnumerateRpsResult Failed(string error) =>
            new() { Success = false, ErrorMessage = error };
    }

    /// <summary>
    /// Result of enumerating credentials for a relying party.
    /// </summary>
    public sealed class EnumerateCredentialsResult : IDisposable
    {
        private bool _disposed;

        public bool Success { get; }
        public string? ErrorMessage { get; }
        public CredentialEnumerationResult? Result { get; }
        public IReadOnlyList<StoredCredentialInfo> Credentials => Result?.Credentials ?? [];

        private EnumerateCredentialsResult(
            bool success,
            string? errorMessage = null,
            CredentialEnumerationResult? result = null)
        {
            Success = success;
            ErrorMessage = errorMessage;
            Result = result;
        }

        public static EnumerateCredentialsResult Succeeded(CredentialEnumerationResult result) =>
            new(true, result: result);

        public static EnumerateCredentialsResult Failed(string error) =>
            new(false, error);

        public void Dispose()
        {
            if (_disposed)
            {
                return;
            }

            Result?.Dispose();
            _disposed = true;
        }
    }

    /// <summary>
    /// Result of a credential management operation (delete, update).
    /// </summary>
    public sealed record CredMgmtResult
    {
        public bool Success { get; init; }
        public string? ErrorMessage { get; init; }

        public static CredMgmtResult Succeeded() => new() { Success = true };
        public static CredMgmtResult Failed(string error) => new() { Success = false, ErrorMessage = error };
    }

    /// <summary>
    /// Gets credential storage metadata (existing count and estimated remaining capacity).
    /// </summary>
    public static async Task<MetadataResult> GetMetadataAsync(
        IYubiKey yubiKey,
        ReadOnlyMemory<byte> pin,
        CancellationToken cancellationToken = default)
    {
        byte[]? pinToken = null;
        try
        {
            await using var session = await yubiKey.CreateCtap2SessionAsync(
                cancellationToken: cancellationToken);

            using var protocol = new PinUvAuthProtocolV2();
            using var clientPin = new ClientPin(session, protocol);

            pinToken = await clientPin.GetPinUvAuthTokenUsingPinAsync(
                pin,
                PinUvAuthTokenPermissions.CredentialManagement,
                cancellationToken: cancellationToken);

            var credMgmt = new Yubico.YubiKit.Ctap2.CredentialManagement.CredentialManagement(
                session, protocol, pinToken);

            var metadata = await credMgmt.GetCredentialsMetadataAsync(cancellationToken);

            return MetadataResult.Succeeded(metadata);
        }
        catch (CtapException ex)
        {
            return MetadataResult.Failed(MapCtapError(ex));
        }
        catch (Exception ex)
        {
            return MetadataResult.Failed($"Failed to get credential metadata: {ex.Message}");
        }
        finally
        {
            if (pinToken is not null)
            {
                CryptographicOperations.ZeroMemory(pinToken);
            }
        }
    }

    /// <summary>
    /// Enumerates relying parties with stored credentials; it does not enumerate their credentials.
    /// </summary>
    public static async Task<EnumerateRpsResult> EnumerateRelyingPartiesAsync(
        IYubiKey yubiKey,
        ReadOnlyMemory<byte> pin,
        CancellationToken cancellationToken = default)
    {
        byte[]? pinToken = null;
        try
        {
            await using var session = await yubiKey.CreateCtap2SessionAsync(
                cancellationToken: cancellationToken);

            using var protocol = new PinUvAuthProtocolV2();
            using var clientPin = new ClientPin(session, protocol);

            pinToken = await clientPin.GetPinUvAuthTokenUsingPinAsync(
                pin,
                PinUvAuthTokenPermissions.CredentialManagement,
                cancellationToken: cancellationToken);

            var credMgmt = new Yubico.YubiKit.Ctap2.CredentialManagement.CredentialManagement(
                session, protocol, pinToken);

            var result = await credMgmt.EnumerateRelyingPartiesAsync(cancellationToken);

            return EnumerateRpsResult.Succeeded(result.RelyingParties);
        }
        catch (CtapException ex)
        {
            return EnumerateRpsResult.Failed(MapCtapError(ex));
        }
        catch (Exception ex)
        {
            return EnumerateRpsResult.Failed($"Failed to enumerate relying parties: {ex.Message}");
        }
        finally
        {
            if (pinToken is not null)
            {
                CryptographicOperations.ZeroMemory(pinToken);
            }
        }
    }

    /// <summary>
    /// Enumerates all credentials for a specific relying party.
    /// </summary>
    /// <remarks>
    /// Pass the returned RpIdHash unchanged, not a hash of potentially truncated RP display text.
    /// Dispose the successful result to clear owned secret-bearing credential envelopes; independent
    /// decoded fields and the underlying response buffers are not all cleared by that disposal.
    /// </remarks>
    public static async Task<EnumerateCredentialsResult> EnumerateCredentialsAsync(
        IYubiKey yubiKey,
        ReadOnlyMemory<byte> pin,
        ReadOnlyMemory<byte> rpIdHash,
        CancellationToken cancellationToken = default)
    {
        byte[]? pinToken = null;
        CredentialEnumerationResult? result = null;
        try
        {
            {
                await using var session = await yubiKey.CreateCtap2SessionAsync(
                    cancellationToken: cancellationToken);

                using var protocol = new PinUvAuthProtocolV2();
                using var clientPin = new ClientPin(session, protocol);

                pinToken = await clientPin.GetPinUvAuthTokenUsingPinAsync(
                    pin,
                    PinUvAuthTokenPermissions.CredentialManagement,
                    cancellationToken: cancellationToken);

                using var credMgmt = new Yubico.YubiKit.Ctap2.CredentialManagement.CredentialManagement(
                    session, protocol, pinToken);

                result = await credMgmt.EnumerateCredentialsAsync(rpIdHash, cancellationToken);
            }

            EnumerateCredentialsResult success = EnumerateCredentialsResult.Succeeded(result);
            result = null;
            return success;
        }
        catch (CtapException ex)
        {
            return EnumerateCredentialsResult.Failed(MapCtapError(ex));
        }
        catch (Exception ex)
        {
            return EnumerateCredentialsResult.Failed($"Failed to enumerate credentials: {ex.Message}");
        }
        finally
        {
            result?.Dispose();
            if (pinToken is not null)
            {
                CryptographicOperations.ZeroMemory(pinToken);
            }
        }
    }

    /// <summary>
    /// Deletes a credential by its ID.
    /// </summary>
    /// <remarks>No undo or automatic associated-large-blob cleanup is performed.</remarks>
    public static async Task<CredMgmtResult> DeleteCredentialAsync(
        IYubiKey yubiKey,
        ReadOnlyMemory<byte> pin,
        ReadOnlyMemory<byte> credentialId,
        CancellationToken cancellationToken = default)
    {
