        {
            return CredMgmtResult.Failed(MapCtapError(ex));
        }
        catch (Exception ex)
        {
            return CredMgmtResult.Failed($"Failed to update user info: {ex.Message}");
        }
        finally
        {
            if (pinToken is not null)
            {
                CryptographicOperations.ZeroMemory(pinToken);
            }
        }
