using Yubico.YubiKit.Core.Abstractions;
using Yubico.YubiKit.Core.Devices;
using Yubico.YubiKit.Core.Protocols.SmartCard.Apdu;
using Yubico.YubiKit.Core.Protocols.SmartCard.Scp;
using Yubico.YubiKit.Core.Sessions;

namespace Yubico.YubiKit.Ctap2;

/// <summary>
/// Extension methods for creating CTAP2 sessions from YubiKey devices.
/// </summary>
/// <remarks>
/// These extension methods provide a convenient API for working with CTAP2
/// functionality on YubiKey devices. They automatically handle connection management
/// and session creation.
/// </remarks>
public static class IYubiKeyExtensions
{
    extension(IYubiKey yubiKey)
    {
        /// <summary>
        /// Gets CTAP2 authenticator information from a YubiKey asynchronously.
        /// </summary>
        /// <param name="options">Optional cross-cutting session creation settings.</param>
        /// <param name="cancellationToken">An optional token to cancel the operation.</param>
        /// <returns>
        /// An <see cref="AuthenticatorInfo"/> containing detailed information about the 
        /// authenticator's capabilities, supported extensions, and options.
        /// </returns>
        /// <remarks>
        /// <para>
        /// This is a convenience method that creates a temporary CTAP2 session, retrieves
        /// the authenticator info, and disposes of the session and its owned connection. Creation
        /// performs an initial GetInfo probe; this method then sends a second, fresh GetInfo read.
        /// It needs no PIN or presence for GetInfo itself. For multiple operations,
        /// use <c>CreateCtap2SessionAsync</c> instead to reuse the session.
        /// </para>
        /// </remarks>
        /// <example>
        /// Composable fragment with an available <see cref="IYubiKey"/> named yubiKey; reported
        /// version advertisement is not certification or support for every optional feature.
        /// <code>
        /// var info = await yubiKey.GetCtap2InfoAsync();
        /// Console.WriteLine($"AAGUID: {Convert.ToHexString(info.Aaguid.Span)}");
        /// Console.WriteLine($"Supports CTAP2.1: {info.Versions.Contains("FIDO_2_1")}");
        /// </code>
        /// </example>
        public async Task<AuthenticatorInfo> GetCtap2InfoAsync(
            SessionCreationOptions? options = null,
            CancellationToken cancellationToken = default)
        {
            await using var session = await yubiKey.CreateCtap2SessionAsync(options, cancellationToken)
                .ConfigureAwait(false);
            return await session.GetInfoAsync(cancellationToken).ConfigureAwait(false);
        }

        /// <summary>
        /// Creates a CTAP2 session for interacting with a YubiKey asynchronously.
        /// </summary>
        /// <param name="options">
        /// Optional creation settings. CTAP2 selects HID FIDO, then SmartCard unless
        /// <see cref="SessionCreationOptions.PreferredConnectionType" /> specifies a supported transport.
        /// Secure-channel parameters force SmartCard when no preference is specified.
        /// </param>
        /// <param name="cancellationToken">An optional token to cancel the operation.</param>
        /// <returns>
        /// A <see cref="Ctap2Session"/> instance configured for the YubiKey device.
        /// The session must be disposed by the caller when no longer needed.
        /// </returns>
        /// <exception cref="NotSupportedException">
        /// Thrown if the YubiKey does not expose a FIDO-capable connection
        /// (<see cref="ConnectionType.HidFido"/> or <see cref="ConnectionType.SmartCard"/>), or if an
        /// explicitly preferred connection is valid for CTAP2 but not exposed by this device.
        /// </exception>
        /// <exception cref="ArgumentException">
        /// Thrown if the preferred connection is not a single concrete transport or is a
        /// transport CTAP2 cannot use (for example <see cref="ConnectionType.HidOtp"/>).
        /// </exception>
        /// <exception cref="ConnectionInUseException">The physical YubiKey already has a live connection.</exception>
        /// <remarks>
        /// <para>
        /// CTAP2 sessions can be created over two transport types:
        /// <list type="bullet">
        /// <item><description>FIDO HID: Uses CTAP HID protocol for USB communication (the default first choice)</description></item>
        /// <item><description>SmartCard (CCID): Uses ISO 7816-4 APDUs over the FIDO AID (NFC, or USB on firmware 5.8.0+)</description></item>
        /// </list>
        /// When a device exposes both, the default selects HID FIDO. Set
        /// <see cref="SessionCreationOptions.PreferredConnectionType" /> to
        /// <see cref="ConnectionType.SmartCard"/> to force SmartCard.
        /// </para>
        /// <para>
        /// SCP (Secure Channel Protocol) is supported only on SmartCard. Supplying
        /// secure-channel parameters without an explicit preference selects SmartCard automatically.
        /// Explicitly selecting HID FIDO with SCP parameters causes session initialization to throw
        /// <see cref="NotSupportedException"/> before HID channel initialization or GetInfo.
        /// </para>
        /// <para>
        /// The returned session owns the opened connection; dispose it before opening another session
        /// on the same physical YubiKey. Connection failures do not trigger another transport attempt.
        /// Caller-supplied SCP parameters and UserPresencePrompt remain caller-owned. SmartCard
        /// selection and GetInfo precede the detected-firmware USB gate and SCP establishment;
        /// FirmwareVersionOverride changes configured session firmware, not that gate's detected value.
        /// Major == 0 sentinel/missing firmware passes Feature's optimistic check, not a hardware
        /// firmware qualification. SCP authentication does not grant CTAP PIN/UV token permissions.
        /// </para>
        /// </remarks>
        /// <example>
        /// Two alternative composable fragments with an available <see cref="IYubiKey"/> named yubiKey.
        /// The SCP03 alternative requires an authorized SmartCard device provisioned with the supplied
        /// default keys; the defaults are not a production key-management recommendation.
        /// <code>
        /// // Ordinary session: dispose before opening another connection on this physical key.
        /// {
        ///     await using var session = await yubiKey.CreateCtap2SessionAsync();
        ///     var info = await session.GetInfoAsync();
        /// }
        /// 
        /// // Alternative: SCP03 over SmartCard on a device provisioned for these keys.
        /// using var scpKeys = Scp03KeyParameters.Default;
        /// await using var secureSession = await yubiKey.CreateCtap2SessionAsync(
        ///     new SessionCreationOptions
        ///     {
        ///         ScpKeyParameters = scpKeys,
        ///         PreferredConnectionType = ConnectionType.SmartCard
        ///     });
        /// </code>
        /// </example>
        public async Task<Ctap2Session> CreateCtap2SessionAsync(
            SessionCreationOptions? options = null,
            CancellationToken cancellationToken = default)
        {
            var scpKeyParams = options?.ScpKeyParameters;
            var preferredConnectionType = options?.PreferredConnectionType;
            var transport = yubiKey.ResolveCtap2SessionTransport(
                scpKeyParams is not null && preferredConnectionType is null
                    ? ConnectionType.SmartCard
                    : preferredConnectionType);
            var sessionOptions = (options ?? new SessionCreationOptions())
                .WithPreferredConnectionType(transport);

            return await yubiKey.CreateSessionOverTransportAsync(
                    transport,
                    async (connection, ct) =>
                    {
                        var session = await Ctap2Session
                            .CreateAsync(
                                connection,
                                sessionOptions,
                                ct)
                            .ConfigureAwait(false);

                        // This entry point opened the connection, so the session it returns is the only thing
                        // that can close it. A caller-created connection is never owned this way.
                        session.OwnConnection();
                        return session;
                    },
                    cancellationToken)
                .ConfigureAwait(false);
        }

        /// <summary>
        /// Resolves the single transport selected for CTAP2.
        /// </summary>
        /// <param name="preferredConnection">Optional explicit transport override (see CreateCtap2SessionAsync).</param>
        /// <returns>The selected CTAP2 transport.</returns>
        private ConnectionType ResolveCtap2SessionTransport(ConnectionType? preferredConnection)
        {
            // CTAP2 is dual-transport (HID FIDO or SmartCard CTAP2). The app-specific smart default selects
            // the first exposed transport: HID FIDO, otherwise SmartCard (NFC, or USB on firmware 5.8.0+).
            // Select one transport so a held HID FIDO interface cannot silently create a second Ctap2Session
            // over SmartCard on the same physical key. Callers can still force either transport explicitly.
            try
            {
                return yubiKey.ResolveSessionTransport(
                    preferredConnection,
                    "CTAP2",
                    Ctap2TransportOrder);
            }
            catch (NotSupportedException) when (preferredConnection is null)
            {
                // The remap stays scoped to the resolve call ONLY: only the default path (no override) remaps
                // to the FIDO-specific "no FIDO-capable connection" message. An explicit-override failure
                // carries an accurate, override-specific diagnostic from ResolveSessionTransport (e.g. "does
                // not expose the requested SmartCard connection"). Connection failures surface unchanged.
                throw new NotSupportedException(
                    $"This YubiKey does not expose a FIDO-capable connection (available: {yubiKey.AvailableConnections}). " +
                    "CTAP2 requires HID FIDO or SmartCard.");
            }
        }
    }

    // CTAP2 default transport order: HID FIDO first (primary USB CTAP2 interface), then SmartCard CTAP2.
    private static readonly ConnectionType[] Ctap2TransportOrder =
        [ConnectionType.HidFido, ConnectionType.SmartCard];
}

