/// <summary>
/// Extended integration tests for CTAP2 credential management operations.
/// Checks updated display name and presence of two created IDs in credential enumeration for one RP.
/// </summary>
/// <remarks>
/// Default known-PIN normalization precedes capability checks and can set/change the PIN
/// or consume retries. These are human-approved PIN/credential operations on a known-state
/// test device. The update assertion does not check Name, user-handle/public-key preservation
/// or all stored fields. Cleanup deletes all discoverable credentials for the shared test RP,
/// not only the IDs created here. Finally schedules that cleanup but does not guarantee success;
/// make tokens are not cleared and management tokens are cleared only on successful paths.
/// </remarks>
[Trait("Category", "Integration")]
[Trait("Feature", "CredentialManagement")]
public class Ctap2CredentialManagementExtendedTests
{
    [SkippableTheory]
    [WithYubiKey(ConnectionType = ConnectionType.HidFido)]
    [Trait(TestCategories.Category, TestCategories.RequiresUserPresence)]
    public async Task UpdateUserInformation_ChangesDisplayName(YubiKeyTestState state) =>
        await state.WithCtap2SessionAsync(async session =>
        {
            var info = await session.GetInfoAsync();
            if (!info.Options.TryGetValue("credMgmt", out var credMgmtSupported) || !credMgmtSupported)
            {
                Skip.If(true, "YubiKey does not support credential management (credMgmt option)");
                return;
            }

            // This test's version gate permits FIDO_2_1/FIDO_2_1_PRE only; it is not complete subcommand negotiation.
            var supportsPermissions = info.Versions.Contains("FIDO_2_1") ||
                                       info.Versions.Contains("FIDO_2_1_PRE");
            if (!supportsPermissions)
            {
                Skip.If(true, "UpdateUserInformation requires CTAP 2.1");
                return;
            }

            byte[]? credentialId = null;

            try
            {
                using var clientPin = await Ctap2TestHelpers.SetOrVerifyPinAsync(session, Ctap2TestData.PinUtf8);

                var rp = Ctap2TestData.CreateRelyingParty();
                var userId = Ctap2TestData.GenerateUserId();
                var user = Ctap2TestData.CreateUser(userId);
                var makeChallenge = Ctap2TestData.GenerateChallenge();

                var makePinToken = await clientPin.GetPinUvAuthTokenUsingPinAsync(
                    Ctap2TestData.PinUtf8,
                    PinUvAuthTokenPermissions.MakeCredential,
                    Ctap2TestData.RpId);

                var makePinUvAuthParam = Ctap2TestHelpers.ComputeMakeCredentialAuthParam(
                    clientPin.Protocol, makePinToken, makeChallenge);

                var makeResult = await session.MakeCredentialAsync(
                    clientDataHash: makeChallenge,
                    rp: rp,
                    user: user,
                    pubKeyCredParams: Ctap2TestData.ES256Params,
                    options: new MakeCredentialOptions
                    {
                        ResidentKey = true,
                        PinUvAuthParam = makePinUvAuthParam,
                        PinUvAuthProtocol = clientPin.Protocol.Version
                    });

                credentialId = makeResult.GetCredentialId().ToArray();

                // Update the user display name
                var (pinToken, clientPinForCredMan, protocol) = await Ctap2TestHelpers.GetCredManTokenAsync(
                    session, Ctap2TestData.PinUtf8);

                using (clientPinForCredMan)
                {
                    using var credMan = new CredentialManagementClass(session, protocol, pinToken);

                    var updatedUser = new PublicKeyCredentialUserEntity(
                        userId,
                        "updated-user@example.com",
                        "Updated Display Name");

                    var descriptor = new PublicKeyCredentialDescriptor(credentialId);
                    await credMan.UpdateUserInformationAsync(descriptor, updatedUser);

                    // Re-enumerate and assert the matching ID's display name only; other updated/preserved fields are unchecked.
                    var rpIdHash = SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(Ctap2TestData.RpId));
                    using var result = await credMan.EnumerateCredentialsAsync(rpIdHash);

                    var updated = result.Credentials.FirstOrDefault(c =>
                        c.CredentialId.Id.Span.SequenceEqual(credentialId));

                    Assert.NotNull(updated);
                    Assert.Equal("Updated Display Name", updated.User.DisplayName);
                }

                CryptographicOperations.ZeroMemory(pinToken);
            }
            finally
            {
                await Ctap2TestHelpers.DeleteAllCredentialsForRpAsync(session, Ctap2TestData.RpId, Ctap2TestData.PinUtf8);
            }
        });

