using System.Formats.Cbor;
using System.Security.Cryptography;
using Yubico.YubiKit.Ctap2.Credentials;

namespace Yubico.YubiKit.Ctap2.UnitTests.Credentials;

/// <summary>
/// Unit tests for MakeCredentialResponse and GetAssertionResponse decoding.
/// </summary>
/// <remarks>
/// Signatures and zero-coordinate public keys are synthetic parsing fixtures, not cryptographic proofs.
/// Missing-descriptor cases pin decoder permissiveness/fallbacks; CTAP 2.0 permits omission only for
/// an exactly singleton request allowList, while CTAP 2.1/2.3 require the descriptor.
/// </remarks>
public class CredentialResponseTests
{
    /// <summary>
    /// Creates a minimal MakeCredential CBOR response for testing.
    /// </summary>
    private static byte[] CreateMakeCredentialResponse(string format = "none", bool includeUnknown = false)
    {
        var writer = new CborWriter(CborConformanceMode.Ctap2Canonical);

        writer.WriteStartMap(includeUnknown ? 4 : 3);

        // 0x01: fmt
        writer.WriteInt32(1);
        writer.WriteTextString(format);

        // 0x02: authData (37-byte fixed prefix with AT, followed by complete synthetic attested fields)
        writer.WriteInt32(2);
        var authData = CreateAuthDataWithAttestedCredentialData();
        writer.WriteByteString(authData);

        // 0x03: attStmt — shape depends on format
        writer.WriteInt32(3);
        if (format == "packed")
        {
            // Packed attestation alg/sig fields are defined by WebAuthn L2 §8.2; signature bytes below are synthetic.
            writer.WriteStartMap(2);
            writer.WriteTextString("alg");
            writer.WriteInt32(-7); // ES256
            writer.WriteTextString("sig");
            writer.WriteByteString(new byte[] { 0x30, 0x44 }); // minimal signature placeholder
            writer.WriteEndMap();
        }
        else
        {
            // "none" has empty attStmt per WebAuthn L2 §8.7, not signed self attestation.
            writer.WriteStartMap(0);
            writer.WriteEndMap();
        }

        if (includeUnknown)
        {
            writer.WriteInt32(99);
            writer.WriteTextString("future");
        }

        writer.WriteEndMap();

        return writer.Encode();
    }

    private static byte[] CreateAuthDataWithAttestedCredentialData()
    {
        // rpIdHash (32) + flags (1) + signCount (4) + AAGUID (16) + credIdLen (2) + credId + publicKey
        var data = new List<byte>();

        // rpIdHash (32 bytes)
        var rpIdHash = new byte[32];
        SHA256.HashData("example.com"u8, rpIdHash);
        data.AddRange(rpIdHash);

        // flags = UP | AT (0x41)
        data.Add(0x41);

        // signCount (4 bytes, big-endian)
        data.AddRange(new byte[] { 0x00, 0x00, 0x00, 0x01 });

        // AAGUID (16 bytes, all zeros for this test)
        data.AddRange(new byte[16]);

        // Credential ID length (2 bytes, big-endian) = 32
        data.AddRange(new byte[] { 0x00, 0x20 });

        // Credential ID (32 bytes)
        var credId = new byte[32];
        new Random(42).NextBytes(credId);
        data.AddRange(credId);

        // COSE public key (minimal EC2 key in CBOR)
        var keyWriter = new CborWriter(CborConformanceMode.Ctap2Canonical);
        keyWriter.WriteStartMap(5);

        // kty = 2 (EC2)
        keyWriter.WriteInt32(1);
        keyWriter.WriteInt32(2);

        // alg = -7 (ES256)
        keyWriter.WriteInt32(3);
        keyWriter.WriteInt32(-7);

        // crv = 1 (P-256)
        keyWriter.WriteInt32(-1);
        keyWriter.WriteInt32(1);

        // x coordinate (32 bytes)
        keyWriter.WriteInt32(-2);
        keyWriter.WriteByteString(new byte[32]);

        // y coordinate (32 bytes)
        keyWriter.WriteInt32(-3);
        keyWriter.WriteByteString(new byte[32]);

        keyWriter.WriteEndMap();
        data.AddRange(keyWriter.Encode());

        return data.ToArray();
    }

    /// <summary>
    /// Creates a minimal GetAssertion CBOR response for testing.
    /// </summary>
    private static byte[] CreateGetAssertionResponse(
        bool includeCredential = false,
        bool includeUser = false,
        bool includeUnknown = false)
    {
        var writer = new CborWriter(CborConformanceMode.Ctap2Canonical);

        var mapCount = 2; // authData + signature
        if (includeCredential) mapCount++;
        if (includeUser) mapCount++;
        if (includeUnknown) mapCount++;

        writer.WriteStartMap(mapCount);

        // 0x01: credential (optional in this fixture, not universally optional under CTAP)
        if (includeCredential)
        {
            writer.WriteInt32(1);
            writer.WriteStartMap(2);
            writer.WriteTextString("type");
            writer.WriteTextString("public-key");
            writer.WriteTextString("id");
            writer.WriteByteString([0x01, 0x02, 0x03, 0x04]);
            writer.WriteEndMap();
        }

        // 0x02: authData (minimal: 37 bytes)
        writer.WriteInt32(2);
        var authData = CreateMinimalAuthData();
        writer.WriteByteString(authData);

        // 0x03: signature
        writer.WriteInt32(3);
        writer.WriteByteString([0x30, 0x44]); // Minimal signature

        // 0x04: user (optional)
        if (includeUser)
        {
            writer.WriteInt32(4);
            writer.WriteStartMap(3);
            writer.WriteTextString("id");
            writer.WriteByteString([0xAA, 0xBB]);
            writer.WriteTextString("name");
            writer.WriteTextString("testuser");
            writer.WriteTextString("displayName");
            writer.WriteTextString("Test User");
            writer.WriteEndMap();
        }

        if (includeUnknown)
        {
            writer.WriteInt32(99);
            writer.WriteStartArray(1);
            writer.WriteTextString("future");
            writer.WriteEndArray();
        }

        writer.WriteEndMap();

        return writer.Encode();
    }

    private static byte[] CreateMinimalAuthData()
    {
        var data = new byte[37];
        SHA256.HashData("example.com"u8, data.AsSpan(0, 32));
        data[32] = 0x05; // UP + UV
        data[33] = 0x00;
        data[34] = 0x00;
        data[35] = 0x00;
        data[36] = 0x05;
        return data;
    }

    [Fact]
    public void MakeCredentialResponse_Decode_ParsesFormat()
    {
        var cbor = CreateMakeCredentialResponse("packed");

        var response = MakeCredentialResponse.Decode(cbor);

        Assert.Equal("packed", response.Format);
    }

    [Fact]
    public void MakeCredentialResponse_Decode_IgnoresUnknownField()
    {
        byte[] cbor = CreateMakeCredentialResponse(includeUnknown: true);
        var response = MakeCredentialResponse.Decode(cbor);

        Assert.Equal("none", response.Format);
        Assert.True(response.AuthenticatorData.UserPresent);
    }

    [Fact]
    public void MakeCredentialResponse_DecodeFromReader_ParsesOneValue()
    {
        byte[] cbor = CreateMakeCredentialResponse("packed", includeUnknown: true);
        var writer = new CborWriter(CborConformanceMode.Lax, convertIndefiniteLengthEncodings: false, allowMultipleRootLevelValues: true);
        writer.WriteBoolean(true);
        writer.WriteEncodedValue(cbor);
        var reader = new CborReader(
            writer.Encode(),
            CborConformanceMode.Ctap2Canonical,
            allowMultipleRootLevelValues: true);
        Assert.True(reader.ReadBoolean());

        var response = MakeCredentialResponse.Decode(reader);

        Assert.Equal("packed", response.Format);
        Assert.Equal([0xA2, 0x63, 0x61, 0x6C, 0x67, 0x26, 0x63, 0x73, 0x69, 0x67, 0x42, 0x30, 0x44],
            response.AttestationStatement.RawCbor.ToArray());
        Assert.Equal(CborReaderState.Finished, reader.PeekState());
    }

