    private static byte[] MinimalGetInfoResponse()
    {
        // Versions-only fake probe; not a conforming GetInfo envelope (required AAGUID is omitted).
        var writer = new CborWriter(CborConformanceMode.Ctap2Canonical);
        writer.WriteStartMap(1);
        writer.WriteInt32(0x01);
        writer.WriteStartArray(1);
        writer.WriteTextString("FIDO_2_0");
        writer.WriteEndArray();
        writer.WriteEndMap();
        return writer.Encode();
    }

    private static UserPresenceContext CreatePolicyContext() => new()
    {
        Basis = UserPresenceBasis.PolicyRequires,
        Application = "FIDO2",
        Scope = "example.com"
    };

    private sealed class TouchWaitingHidConnection(byte[] getInfo) : IFidoHidConnection
    {
        private byte[]? _init;
        private int _responseCount;
        public int PacketSize => CtapConstants.PacketSize;
        public ConnectionType Type => ConnectionType.HidFido;

        public Task SendAsync(ReadOnlyMemory<byte> packet, CancellationToken cancellationToken = default)
        {
            if ((packet.Span[4] & 0x7F) == CtapConstants.CtapHidInit)
                _init = packet.ToArray();
            return Task.CompletedTask;
        }

        public Task<ReadOnlyMemory<byte>> ReceiveAsync(CancellationToken cancellationToken = default)
        {
            byte[] response = _responseCount++ switch
            {
                0 => InitResponse(),
                1 => Packet(0x01020304, CtapConstants.CtapHidCbor, [0x00, .. getInfo]),
                2 => Packet(0x01020304, CtapConstants.CtapHidKeepAlive, [0x02]),
                _ => Packet(0x01020304, CtapConstants.CtapHidCbor, [(byte)CtapStatus.UserActionTimeout])
            };
            return Task.FromResult<ReadOnlyMemory<byte>>(response);
        }

        private byte[] InitResponse()
        {
            var payload = new byte[17];
            (_init ?? throw new InvalidOperationException("INIT not sent"))
                .AsSpan(CtapConstants.InitHeaderSize, 8).CopyTo(payload);
            BinaryPrimitives.WriteUInt32BigEndian(payload.AsSpan(8), 0x01020304);
            payload[12] = 2;
            return Packet(CtapConstants.BroadcastChannelId, CtapConstants.CtapHidInit, payload);
        }

        private static byte[] Packet(uint channel, byte command, ReadOnlySpan<byte> data)
        {
            var packet = new byte[CtapConstants.PacketSize];
            BinaryPrimitives.WriteUInt32BigEndian(packet, channel);
            packet[4] = (byte)(command | 0x80);
            packet[5] = (byte)(data.Length >> 8);
            packet[6] = (byte)data.Length;
            data.CopyTo(packet.AsSpan(CtapConstants.InitHeaderSize));
            return packet;
        }

        public void Dispose() { }
        public ValueTask DisposeAsync() => ValueTask.CompletedTask;
    }

    private sealed class DisposeTrackingSmartCardConnection(params byte[][] responses) : ISmartCardConnection
    {
        private readonly Queue<byte[]> _responses = new(responses);
        private readonly TaskCompletionSource _asyncDisposalStarted = new(
            TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly TaskCompletionSource _resumeAsyncDisposal = new(
            TaskCreationOptions.RunContinuationsAsynchronously);

        public int DisposeCount { get; private set; }
        public int DisposeAsyncCount { get; private set; }
        public Exception? DisposeAsyncException { get; init; }
        public bool PauseAsyncDisposal { get; init; }
        public Task AsyncDisposalStarted => _asyncDisposalStarted.Task;
        public List<byte[]> TransmittedCommands { get; } = [];
        public Transport Transport => Transport.Usb;
        public ConnectionType Type => ConnectionType.SmartCard;

        public Task<ReadOnlyMemory<byte>> TransmitAndReceiveAsync(
            ReadOnlyMemory<byte> command,
            CancellationToken cancellationToken = default)
        {
            TransmittedCommands.Add(command.ToArray());
            return Task.FromResult((ReadOnlyMemory<byte>)_responses.Dequeue());
        }

        public IDisposable BeginTransaction(CancellationToken cancellationToken = default) =>
            NullDisposable.Instance;

        public bool SupportsExtendedApdu() => false;

        public void Dispose() => DisposeCount++;

        public async ValueTask DisposeAsync()
        {
            DisposeAsyncCount++;
            _asyncDisposalStarted.TrySetResult();

            if (PauseAsyncDisposal)
            {
                await _resumeAsyncDisposal.Task.ConfigureAwait(false);
            }

            if (DisposeAsyncException is not null)
            {
                throw DisposeAsyncException;
            }
        }

        public void ResumeAsyncDisposal() => _resumeAsyncDisposal.TrySetResult();
    }

    private sealed class SingleConnectionYubiKey(ISmartCardConnection connection) : IYubiKey
    {
        public string DeviceId => "fido-disposal-probe";
        public ConnectionType AvailableConnections => ConnectionType.SmartCard;

        public Task<TConnection> ConnectAsync<TConnection>(CancellationToken cancellationToken = default)
            where TConnection : class, IConnection =>
            Task.FromResult((connection as TConnection)!);
    }

    private sealed class NullDisposable : IDisposable
    {
        public static NullDisposable Instance { get; } = new();

        public void Dispose()
        {
        }
    }

    private sealed class RecordingUserPresencePrompt(
        Exception? requestException = null,
        Exception? resolutionException = null) : IUserPresencePrompt
    {
        public List<UserPresenceContext> Requested { get; } = [];
        public List<(UserPresenceContext Context, UserPresenceOutcome Outcome, CancellationToken CancellationToken)>
            Resolved
        { get; } = [];

        public ValueTask OnUserPresenceRequestedAsync(
            UserPresenceContext context,
            CancellationToken cancellationToken)
        {
            Requested.Add(context);
            return requestException is null
                ? default
                : ValueTask.FromException(requestException);
        }

        public ValueTask OnUserPresenceResolvedAsync(
            UserPresenceContext context,
            UserPresenceOutcome outcome,
            CancellationToken cancellationToken)
        {
            Resolved.Add((context, outcome, cancellationToken));
            return resolutionException is null
                ? default
                : ValueTask.FromException(resolutionException);
        }
    }
}

using FluentAssertions;
using Yubico.YubiKit.Ctap2;

namespace Yubico.YubiKit.Ctap2.UnitTests;

public class CtapExceptionTests
{
    [Fact]
    public void Constructor_WithStatus_SetsStatus()
    {
        // Arrange & Act
        var exception = new CtapException(CtapStatus.PinInvalid);

        // Assert
        exception.Status.Should().Be(CtapStatus.PinInvalid);
        exception.Message.Should().Contain("PIN");
    }

    [Fact]
    public void Constructor_WithStatusAndMessage_SetsProperties()
    {
        // Arrange & Act
        var exception = new CtapException(CtapStatus.NoCredentials, "Custom message");

        // Assert
        exception.Status.Should().Be(CtapStatus.NoCredentials);
        exception.Message.Should().Be("Custom message");
    }

    [Fact]
    public void Constructor_WithInnerException_PreservesInnerException()
    {
        // Arrange
        var inner = new InvalidOperationException("Inner");

        // Act
        var exception = new CtapException(CtapStatus.Other, "Outer", inner);

        // Assert
        exception.InnerException.Should().Be(inner);
    }

    [Fact]
    public void ThrowIfError_WithSuccess_DoesNotThrow()
    {
        // Act & Assert
        var action = () => CtapException.ThrowIfError(CtapStatus.Success);
        action.Should().NotThrow();
    }

    [Fact]
    public void ThrowIfError_WithError_ThrowsException()
    {
        // Act & Assert
        var action = () => CtapException.ThrowIfError(CtapStatus.PinBlocked);
        action.Should().Throw<CtapException>()
            .Which.Status.Should().Be(CtapStatus.PinBlocked);
    }

    [Fact]
    public void ThrowIfError_WithByte_ThrowsException()
    {
        // Act & Assert
        var action = () => CtapException.ThrowIfError((byte)0x32); // PinBlocked
        action.Should().Throw<CtapException>()
            .Which.Status.Should().Be(CtapStatus.PinBlocked);
    }

    // Checks retained numeric values only. PIN_TOKEN_EXPIRED 0x38 is assigned in CTAP2.0,
    // but reserved in CTAP2.1/2.2 RD/2.3; the method name does not imply all-revision assignment.
    [Theory]
    [InlineData(CtapStatus.PinNotSet, 0x35)]
    [InlineData(CtapStatus.PuatRequired, 0x36)]
    [InlineData(CtapStatus.PinTokenExpired, 0x38)]
    [InlineData(CtapStatus.ActionTimeout, 0x3A)]
    [InlineData(CtapStatus.UpRequired, 0x3B)]
    public void Ctap2StatusValues_MatchSpecification(CtapStatus status, byte expectedValue) =>
        ((byte)status).Should().Be(expectedValue);

    [Theory]
    [InlineData(CtapStatus.InvalidCommand, "Invalid CTAP command")]
    [InlineData(CtapStatus.InvalidParameter, "Invalid parameter")]
    [InlineData(CtapStatus.Timeout, "timed out")]
    [InlineData(CtapStatus.CredentialExcluded, "excluded")]
    [InlineData(CtapStatus.NoCredentials, "No credentials")]
    [InlineData(CtapStatus.UserActionTimeout, "timeout")]
    [InlineData(CtapStatus.PuatRequired, "token required")]
    [InlineData(CtapStatus.PinTokenExpired, "token expired")]
    public void Constructor_WithKnownStatus_HasDescriptiveMessage(CtapStatus status, string expectedContains)
    {
        // Arrange & Act
        var exception = new CtapException(status);

        // Assert
        exception.Message.Should().ContainEquivalentOf(expectedContains);
    }
}

using FluentAssertions;
using System.Formats.Cbor;
using Yubico.YubiKit.Ctap2.Cbor;
using Yubico.YubiKit.Ctap2;

namespace Yubico.YubiKit.Ctap2.UnitTests;

/// <summary>Checks command prefixes and selected request-builder values.</summary>
/// <remarks>Most With* cases assert only nonempty payload and command byte. They do not establish
/// complete command schema, allocation behavior or canonical wire order from their method names.</remarks>
public class CtapRequestBuilderTests
{
    [Fact]
    public void Create_WithCommandOnly_ReturnsCommandByte()
    {
        // Arrange & Act
        var result = CtapRequestBuilder.Create(CtapCommand.GetInfo).Build();

        // Assert
        result.Should().HaveCount(1);
        result[0].Should().Be(CtapCommand.GetInfo);
    }

    [Fact]
    public void WithInt_AddsIntegerParameter()
    {
        // Arrange & Act
        var result = CtapRequestBuilder.Create(CtapCommand.ClientPin)
            .WithInt(1, 42)
            .Build();

        // Assert payload presence and command byte only; the map/value is not decoded here.
        result.Should().HaveCountGreaterThan(1);
        result[0].Should().Be(CtapCommand.ClientPin);
    }

    [Fact]
    public void WithString_AddsStringParameter()
    {
        // Arrange & Act
        var result = CtapRequestBuilder.Create(CtapCommand.MakeCredential)
            .WithString(1, "test")
            .Build();

        // Assert
        result.Should().HaveCountGreaterThan(1);
        result[0].Should().Be(CtapCommand.MakeCredential);
    }

    [Fact]
    public void WithBytes_AddsByteArrayParameter()
    {
        // Arrange
        byte[] testData = [0x01, 0x02, 0x03];

        // Act
        var result = CtapRequestBuilder.Create(CtapCommand.GetAssertion)
            .WithBytes(1, testData)
            .Build();

        // Assert
        result.Should().HaveCountGreaterThan(1);
        result[0].Should().Be(CtapCommand.GetAssertion);
    }

    [Fact]
    public void WithBool_AddsBooleanParameter()
    {
        // Arrange & Act
        var result = CtapRequestBuilder.Create(CtapCommand.Config)
            .WithBool(1, true)
            .Build();

        // Assert
        result.Should().HaveCountGreaterThan(1);
        result[0].Should().Be(CtapCommand.Config);
    }

    [Fact]
    public void WithValue_WritesParameterWithoutIntermediateCopy()
    {
        // Decodes the key/value; no allocation measurement establishes the method name's copy claim.
        // Arrange & Act
        var result = CtapRequestBuilder.Create(CtapCommand.MakeCredential)
            .WithValue(1, writer => writer.WriteByteString([0xAA, 0xBB]))
            .Build();

        // Assert
        result[0].Should().Be(CtapCommand.MakeCredential);
        var reader = new CborReader(result.AsSpan(1).ToArray(), CborConformanceMode.Ctap2Canonical);
        reader.ReadStartMap().Should().Be(1);
        reader.ReadInt32().Should().Be(1);
        reader.ReadByteString().Should().Equal([0xAA, 0xBB]);
        reader.ReadEndMap();
    }

    [Fact]
    public void MultipleParameters_SortedByKey()
    {
        // Arrange & Act - add parameters out of order
        var result = CtapRequestBuilder.Create(CtapCommand.MakeCredential)
            .WithInt(3, 300)
            .WithInt(1, 100)
            .WithInt(2, 200)
            .Build();

        // Assert prefix/payload presence only; this test does not inspect the key order.
        result.Should().HaveCountGreaterThan(1);
        result[0].Should().Be(CtapCommand.MakeCredential);
        // Exact encoded-key order needs a separate byte-level assertion, not this length check.
    }

    [Fact]
    public void BuildAsMemory_ReturnsReadOnlyMemory()
    {
        // Arrange & Act
        var result = CtapRequestBuilder.Create(CtapCommand.GetInfo).BuildAsMemory();

        // Assert
        result.Length.Should().Be(1);
        result.Span[0].Should().Be(CtapCommand.GetInfo);
    }
}

