using System.Formats.Cbor;
using Yubico.YubiKit.Ctap2.Extensions;

namespace Yubico.YubiKit.Ctap2.UnitTests.Extensions;

public class HmacSecretInputTests
{
    [Fact]
    public void HmacSecretInput_EncodesCorrectly()
    {
        // Synthetic P-256-shaped dictionary: this fixture asserts only nonempty encoding/map count,
        // not key-agreement coherence, all nested bytes or protocol cryptography.
        var keyAgreement = new Dictionary<int, object?>
        {
            { 1, 2 },
            { 3, -25 },
            { -1, 1 },
            { -2, new byte[32] },
            { -3, new byte[32] }
        };

        var input = new HmacSecretInput
        {
            KeyAgreement = keyAgreement,
            SaltEnc = new byte[48],
            SaltAuth = new byte[32],
            PinUvAuthProtocol = 2
        };

        var encoded = input.Encode();

        Assert.NotEmpty(encoded);

        var reader = new CborReader(encoded, CborConformanceMode.Lax);
        var mapCount = reader.ReadStartMap();
        Assert.Equal(4, mapCount);
    }
}

