    [Fact]
    public void Build_WithMultipleExtensions_EncodesAllCorrectly()
    {
        // Arrange
        var builder = new ExtensionBuilder()
            .WithCredProtect(CredProtectPolicy.UserVerificationOptionalWithCredentialIdList)
            .WithCredBlob(new byte[] { 1, 2, 3 })
            .WithMinPinLength();

        // Act
