using Yubico.YubiKit.Core.Abstractions;
using Yubico.YubiKit.Core.Devices;
using Yubico.YubiKit.Core.Protocols.Fido.Hid;
using Yubico.YubiKit.Core.Protocols.SmartCard.Scp;
using Yubico.YubiKit.Core.Sessions;
using Yubico.YubiKit.Core.Transports.SmartCard;

namespace Yubico.YubiKit.Ctap2.UnitTests;

/// <summary>
///     Checks CTAP2 transport selection and explicit preference using a fake connect probe.
///     The probe records the requested type and fails before protocol initialization or device operations.
/// </summary>
public class IYubiKeyExtensionsTransportTests
{
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    // (a) default top-choice: both transports present -> HID FIDO.
    [Fact]
    public async Task CreateCtap2SessionAsync_DefaultBothTransports_PicksHidFido()
    {
        var device = new SelectionProbeYubiKey(ConnectionType.HidFido | ConnectionType.SmartCard);

        await Assert.ThrowsAsync<ConnectProbeException>(() => device.CreateCtap2SessionAsync(cancellationToken: Ct));

        Assert.Equal(typeof(IFidoHidConnection), device.RequestedConnection);
    }

    // SmartCard is selected when HID FIDO is absent, not retried after a HID connection failure.
    [Fact]
    public async Task CreateCtap2SessionAsync_DefaultSmartCardOnly_FallsBackToSmartCard()
    {
        var device = new SelectionProbeYubiKey(ConnectionType.SmartCard);

        await Assert.ThrowsAsync<ConnectProbeException>(() => device.CreateCtap2SessionAsync(cancellationToken: Ct));

        Assert.Equal(typeof(ISmartCardConnection), device.RequestedConnection);
    }

    [Fact]
    public async Task CreateCtap2SessionAsync_SingleHidFido_RoutesToFidoTransport()
    {
        var device = new SelectionProbeYubiKey(ConnectionType.HidFido);

        await Assert.ThrowsAsync<ConnectProbeException>(() => device.CreateCtap2SessionAsync(cancellationToken: Ct));

        Assert.Equal(typeof(IFidoHidConnection), device.RequestedConnection);
    }

    // (c) explicit non-default override on a multi-transport device beats the default order.
    [Fact]
    public async Task CreateCtap2SessionAsync_OverrideSmartCard_OnBothTransports_UsesSmartCard()
    {
        var device = new SelectionProbeYubiKey(ConnectionType.HidFido | ConnectionType.SmartCard);

        await Assert.ThrowsAsync<ConnectProbeException>(
            () => device.CreateCtap2SessionAsync(
                new SessionCreationOptions { PreferredConnectionType = ConnectionType.SmartCard }, Ct));

        Assert.Equal(typeof(ISmartCardConnection), device.RequestedConnection);
    }

    // (d) device-unsupported but applet-valid override -> NotSupportedException, no connect attempt.
    [Fact]
    public async Task CreateCtap2SessionAsync_OverrideSmartCard_NotOnDevice_ThrowsNotSupported()
    {
        var device = new SelectionProbeYubiKey(ConnectionType.HidFido);

        await Assert.ThrowsAsync<NotSupportedException>(
            () => device.CreateCtap2SessionAsync(
                new SessionCreationOptions { PreferredConnectionType = ConnectionType.SmartCard }, Ct));

        Assert.Null(device.RequestedConnection);
    }

    // (e) non-concrete override values -> ArgumentException, no connect attempt.
    [Theory]
    [InlineData(ConnectionType.Hid)]
    [InlineData(ConnectionType.All)]
    [InlineData(ConnectionType.Unknown)]
    [InlineData(ConnectionType.HidFido | ConnectionType.SmartCard)]
    public async Task CreateCtap2SessionAsync_NonConcreteOverride_ThrowsArgumentException(ConnectionType invalid)
    {
        var device = new SelectionProbeYubiKey(ConnectionType.HidFido | ConnectionType.SmartCard);

        await Assert.ThrowsAsync<ArgumentException>(
            () => device.CreateCtap2SessionAsync(
                new SessionCreationOptions { PreferredConnectionType = invalid }, Ct));

        Assert.Null(device.RequestedConnection);
    }

    // (f) applet-invalid concrete override (HID OTP) -> ArgumentException even when the device exposes it.
    [Fact]
    public async Task CreateCtap2SessionAsync_OverrideHidOtp_AppletInvalid_ThrowsArgumentException()
    {
        var device = new SelectionProbeYubiKey(ConnectionType.HidFido | ConnectionType.HidOtp);

        await Assert.ThrowsAsync<ArgumentException>(
            () => device.CreateCtap2SessionAsync(
                new SessionCreationOptions { PreferredConnectionType = ConnectionType.HidOtp }, Ct));

        Assert.Null(device.RequestedConnection);
    }

    // (h) no FIDO-capable transport -> NotSupportedException, no connect attempt.
    [Theory]
    [InlineData(ConnectionType.HidOtp)]
    [InlineData(ConnectionType.Unknown)]
    public async Task CreateCtap2SessionAsync_NoFidoCapableTransport_ThrowsNotSupported(ConnectionType available)
    {
        var device = new SelectionProbeYubiKey(available);

        await Assert.ThrowsAsync<NotSupportedException>(() => device.CreateCtap2SessionAsync(cancellationToken: Ct));

        Assert.Null(device.RequestedConnection);
    }

    // (i) SCP implies SmartCard when no explicit transport override is supplied because SCP is SmartCard-only.
    [Fact]
    public async Task CreateCtap2SessionAsync_ScpWithDefault_RoutesToSmartCard()
    {
        var device = new SelectionProbeYubiKey(ConnectionType.HidFido | ConnectionType.SmartCard);
        using var scp = Scp03KeyParameters.Default;

        await Assert.ThrowsAsync<ConnectProbeException>(
            () => device.CreateCtap2SessionAsync(
                new SessionCreationOptions { ScpKeyParameters = scp }, Ct));

        Assert.Equal(typeof(ISmartCardConnection), device.RequestedConnection);
    }

    // Connection failure after successful resolution must retain its diagnostic, rather than
    // being masked by the resolve-only "no FIDO-capable connection" translation.
    [Fact]
    public async Task CreateCtap2SessionAsync_ConnectFailsNonHeld_SurfacesErrorNotGenericRemap()
    {
        var device = new ThrowingProbeYubiKey(
            ConnectionType.HidFido | ConnectionType.SmartCard,
            new InvalidOperationException("transport boom"));

        var ex = await Assert.ThrowsAsync<InvalidOperationException>(
            () => device.CreateCtap2SessionAsync(cancellationToken: Ct));

        Assert.Equal("transport boom", ex.Message);
    }

    [Fact]
    public async Task CreateCtap2SessionAsync_HidFidoHeld_DoesNotOpenSecondSessionOverSmartCard()
    {
        var device = new HeldHidProbeYubiKey();

        _ = await Assert.ThrowsAsync<ConnectionInUseException>(
            () => device.CreateCtap2SessionAsync(cancellationToken: Ct));

        Assert.Equal([typeof(IFidoHidConnection)], device.RequestedConnections);
    }

    private sealed class SelectionProbeYubiKey(ConnectionType available) : IYubiKey
    {
        public string DeviceId => "probe";
        public ConnectionType AvailableConnections { get; } = available;
        public Type? RequestedConnection { get; private set; }

        public Task<TConnection> ConnectAsync<TConnection>(CancellationToken cancellationToken = default)
            where TConnection : class, IConnection
        {
            RequestedConnection = typeof(TConnection);
            throw new ConnectProbeException();
        }
    }

    // Resolves a transport successfully, then throws a caller-supplied exception from the connect itself.
    private sealed class ThrowingProbeYubiKey(ConnectionType available, Exception connectException) : IYubiKey
    {
        public string DeviceId => "throwing-probe";
        public ConnectionType AvailableConnections { get; } = available;

        public Task<TConnection> ConnectAsync<TConnection>(CancellationToken cancellationToken = default)
            where TConnection : class, IConnection =>
            throw connectException;
    }

    private sealed class HeldHidProbeYubiKey : IYubiKey
    {
        public string DeviceId => "held-hid-probe";
        public ConnectionType AvailableConnections => ConnectionType.HidFido | ConnectionType.SmartCard;
        public List<Type> RequestedConnections { get; } = [];

        public Task<TConnection> ConnectAsync<TConnection>(CancellationToken cancellationToken = default)
            where TConnection : class, IConnection
        {
            RequestedConnections.Add(typeof(TConnection));
            if (typeof(TConnection) == typeof(IFidoHidConnection))
                throw new ConnectionInUseException("The FIDO HID interface is already in use.");

            throw new ConnectProbeException();
        }
    }

    private sealed class ConnectProbeException : Exception;
}

