/// <remarks>
/// These tests use NSubstitute to mock the ICtap2Session.
/// The concrete FakePinUvAuthProtocol copies encryption/decryption inputs and always accepts Verify.
/// Send counts and non-null tokens do not establish cryptographic interoperability, RP binding,
/// permission fallback or secret clearing. The canonical retry-request cases separately decode
/// and assert the command, ordered keys, protocol version and subcommand.
/// </remarks>
public sealed class ClientPinTests : IDisposable
{
    private readonly ICtap2Session _mockSession;
    private readonly FakePinUvAuthProtocol _fakeProtocol;
    private bool _disposed;

    public ClientPinTests()
    {
        _mockSession = Substitute.For<ICtap2Session>();
        _fakeProtocol = new FakePinUvAuthProtocol();
    }

    private ClientPin CreateClientPin() => new(_mockSession, _fakeProtocol);

    [Fact]
    public void Constructor_WithNullCommands_ThrowsArgumentNullException()
    {
        var protocol = Substitute.For<IPinUvAuthProtocol>();
        Assert.Throws<ArgumentNullException>(() => new ClientPin((ICtap2Session)null!, protocol));
    }

